-- rowstile 0.1.0-dev: rows_handed_on_whole. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '6cfec308f6593f25', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '6cfec308f6593f25' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '6cfec308f6593f25' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '6cfec308f6593f25' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '632435019b4c3e49' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '632435019b4c3e49', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP TRIGGER IF EXISTS "authz_update chat_id, seq, sender_id, bot_id, created_at" ON "ms"."messages";
DROP TRIGGER IF EXISTS "authz_update chat_id, user_id, joined_at, joined_seq" ON "ms"."members";
DROP TRIGGER IF EXISTS "authz_update deleted" ON "ms"."messages";
DROP TRIGGER IF EXISTS "authz_update edited_at" ON "ms"."messages";
DROP TRIGGER IF EXISTS "authz_update id, owner_id" ON "ms"."bots";
DROP TRIGGER IF EXISTS "authz_update id, phone, created_at" ON "ms"."users";
DROP TRIGGER IF EXISTS "authz_update kind, created_by, created_at, last_seq" ON "ms"."chats";
DROP TRIGGER IF EXISTS "authz_update last_read_seq" ON "ms"."members";
DROP TRIGGER IF EXISTS "authz_update role" ON "ms"."members";
DROP TRIGGER IF EXISTS "authz_update_after body" ON "ms"."messages";
DROP TRIGGER IF EXISTS "authz_update_after deleted" ON "ms"."messages";
DROP TRIGGER IF EXISTS "authz_update_after last_read_seq" ON "ms"."members";
DROP TRIGGER IF EXISTS "authz_update_after role" ON "ms"."members";

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'ms_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

CREATE OR REPLACE FUNCTION authz_int."bot__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('bot', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."owner_id" IS DISTINCT FROM o."owner_id" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['active'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['active']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'bot', n."id"::text, 'owner', n."owner_id"::text, jsonb_build_object('column', 'owner_id', 'was', o."owner_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."owner_id" IS DISTINCT FROM o."owner_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'bot'
          AND a.object_id = n."id"::text AND a.relation = 'owner' AND a.detail->>'column' = 'owner_id'
          AND a.subject_id IS NOT DISTINCT FROM n."owner_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."owner_id"));
    END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."chat__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('chat', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."created_by" IS DISTINCT FROM o."created_by" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['admins_only', 'chat_id', 'direct_pairs', 'exists', 'from', 'kind', 'm', 'members', 'ms', 'not', 'p', 'select', 'this', 'where'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['admins_only', 'chat_id', 'direct_pairs', 'exists', 'from', 'kind', 'm', 'members', 'ms', 'not', 'p', 'select', 'this', 'where']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'chat', n."id"::text, 'creator', n."created_by"::text, jsonb_build_object('column', 'created_by', 'was', o."created_by"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."created_by" IS DISTINCT FROM o."created_by" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'chat'
          AND a.object_id = n."id"::text AND a.relation = 'creator' AND a.detail->>'column' = 'created_by'
          AND a.subject_id IS NOT DISTINCT FROM n."created_by"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."created_by"));
    END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."membership__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('membership', ARRAY(
        SELECT ROW(n."chat_id"::bigint, n."user_id"::uuid)::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."user_id"::uuid)::text = ROW(n."chat_id"::bigint, n."user_id"::uuid)::text)
        UNION SELECT ROW(o."chat_id"::bigint, o."user_id"::uuid)::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."chat_id"::bigint, n."user_id"::uuid)::text = ROW(o."chat_id"::bigint, o."user_id"::uuid)::text)
        UNION SELECT ROW(n."chat_id"::bigint, n."user_id"::uuid)::text FROM new_rows n JOIN old_rows o ON ROW(n."chat_id"::bigint, n."user_id"::uuid)::text = ROW(o."chat_id"::bigint, o."user_id"::uuid)::text
        WHERE n."chat_id" IS DISTINCT FROM o."chat_id" OR n."user_id" IS DISTINCT FROM o."user_id" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['c', 'chats', 'from', 'id', 'last_read_seq', 'last_seq', 'ms', 'role', 'select', 'where'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['c', 'chats', 'from', 'id', 'last_read_seq', 'last_seq', 'ms', 'role', 'select', 'where']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'membership', ROW(n."chat_id"::bigint, n."user_id"::uuid)::text, 'chat', n."chat_id"::text, jsonb_build_object('column', 'chat_id', 'was', o."chat_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."chat_id"::bigint, n."user_id"::uuid)::text = ROW(o."chat_id"::bigint, o."user_id"::uuid)::text
      WHERE n."chat_id" IS DISTINCT FROM o."chat_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'membership'
          AND a.object_id = ROW(n."chat_id"::bigint, n."user_id"::uuid)::text AND a.relation = 'chat' AND a.detail->>'column' = 'chat_id'
          AND a.subject_id IS NOT DISTINCT FROM n."chat_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."chat_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'membership', ROW(n."chat_id"::bigint, n."user_id"::uuid)::text, 'person', n."user_id"::text, jsonb_build_object('column', 'user_id', 'was', o."user_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."chat_id"::bigint, n."user_id"::uuid)::text = ROW(o."chat_id"::bigint, o."user_id"::uuid)::text
      WHERE n."user_id" IS DISTINCT FROM o."user_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'membership'
          AND a.object_id = ROW(n."chat_id"::bigint, n."user_id"::uuid)::text AND a.relation = 'person' AND a.detail->>'column' = 'user_id'
          AND a.subject_id IS NOT DISTINCT FROM n."user_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."user_id"));
    END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."chat_bot__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('chat_bot', ARRAY(
        SELECT ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."chat_id"::bigint, o."bot_id"::bigint)::text = ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text)
        UNION SELECT ROW(o."chat_id"::bigint, o."bot_id"::bigint)::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text = ROW(o."chat_id"::bigint, o."bot_id"::bigint)::text)
        UNION SELECT ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text FROM new_rows n JOIN old_rows o ON ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text = ROW(o."chat_id"::bigint, o."bot_id"::bigint)::text
        WHERE n."bot_id" IS DISTINCT FROM o."bot_id" OR n."chat_id" IS DISTINCT FROM o."chat_id" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['added_by', 'authz', 'uid'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['added_by', 'authz', 'uid']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'chat_bot', ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text, 'chat', n."chat_id"::text, jsonb_build_object('column', 'chat_id', 'was', o."chat_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text = ROW(o."chat_id"::bigint, o."bot_id"::bigint)::text
      WHERE n."chat_id" IS DISTINCT FROM o."chat_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'chat_bot'
          AND a.object_id = ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text AND a.relation = 'chat' AND a.detail->>'column' = 'chat_id'
          AND a.subject_id IS NOT DISTINCT FROM n."chat_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."chat_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'chat_bot', ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text, 'bot', n."bot_id"::text, jsonb_build_object('column', 'bot_id', 'was', o."bot_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text = ROW(o."chat_id"::bigint, o."bot_id"::bigint)::text
      WHERE n."bot_id" IS DISTINCT FROM o."bot_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'chat_bot'
          AND a.object_id = ROW(n."chat_id"::bigint, n."bot_id"::bigint)::text AND a.relation = 'bot' AND a.detail->>'column' = 'bot_id'
          AND a.subject_id IS NOT DISTINCT FROM n."bot_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."bot_id"));
    END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."ms.users:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "ms"."users"; r_new "ms"."users";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for ms.users: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'ms.users', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT (jsonb_populate_record(NULL::"ms"."users", to_jsonb(x.*))).* INTO r_old FROM "ms"."people" x WHERE x."id" = p_id::uuid;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for ms.users: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."ms.users:update:why"(r_old, true)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."ms.users:update:why"(r_new, false) l) END;
END $f$;

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update id, phone, created_at" BEFORE UPDATE ON "ms"."users" FOR EACH ROW
  WHEN ((OLD."id" IS DISTINCT FROM NEW."id"
     OR OLD."phone" IS DISTINCT FROM NEW."phone"
     OR OLD."created_at" IS DISTINCT FROM NEW."created_at")
    AND pg_catalog.row_security_active('"ms"."users"'::pg_catalog.regclass)
    AND NOT authz_int."ms.users:column id, phone, created_at:holds"(pg_catalog.to_jsonb(OLD.*), current_user))
  EXECUTE FUNCTION authz_int."ms.users:column id, phone, created_at"();

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update id, owner_id" BEFORE UPDATE ON "ms"."bots" FOR EACH ROW
  WHEN ((OLD."id" IS DISTINCT FROM NEW."id"
     OR OLD."owner_id" IS DISTINCT FROM NEW."owner_id")
    AND pg_catalog.row_security_active('"ms"."bots"'::pg_catalog.regclass)
    AND NOT authz_int."ms.bots:column id, owner_id:holds"(pg_catalog.to_jsonb(OLD.*), current_user))
  EXECUTE FUNCTION authz_int."ms.bots:column id, owner_id"();

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
