    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"ms_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"ms.blocks:delete:items"', '"ms.blocks:delete:why"', '"ms.blocks:insert:items"', '"ms.blocks:insert:refuse"', '"ms.blocks:insert:why"', '"ms.blocks:rules:explain"', '"ms.bots:column id, owner_id:items"', '"ms.bots:column id, owner_id:why"', '"ms.bots:delete:items"', '"ms.bots:delete:why"', '"ms.bots:insert:items"', '"ms.bots:insert:refuse"', '"ms.bots:insert:why"', '"ms.bots:rules:explain"', '"ms.bots:update:items"', '"ms.bots:update:refuse"', '"ms.bots:update:why"', '"ms.chat_bots:delete:items"', '"ms.chat_bots:delete:why"', '"ms.chat_bots:insert:items"', '"ms.chat_bots:insert:refuse"', '"ms.chat_bots:insert:why"', '"ms.chat_bots:rules:explain"', '"ms.chats:column kind, created_by, created_at, last_seq:items"', '"ms.chats:column kind, created_by, created_at, last_seq:why"', '"ms.chats:delete:items"', '"ms.chats:delete:why"', '"ms.chats:insert:items"', '"ms.chats:insert:refuse"', '"ms.chats:insert:why"', '"ms.chats:rules:explain"', '"ms.chats:update:items"', '"ms.chats:update:refuse"', '"ms.chats:update:why"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:items"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:why"', '"ms.members:column last_read_seq after:items"', '"ms.members:column last_read_seq after:why"', '"ms.members:column last_read_seq:items"', '"ms.members:column last_read_seq:why"', '"ms.members:column role after:items"', '"ms.members:column role after:why"', '"ms.members:column role:items"', '"ms.members:column role:why"', '"ms.members:delete:items"', '"ms.members:delete:why"', '"ms.members:insert:items"', '"ms.members:insert:refuse"', '"ms.members:insert:why"', '"ms.members:rules:explain"', '"ms.members:update:items"', '"ms.members:update:refuse"', '"ms.members:update:why"', '"ms.messages:column body after:items"', '"ms.messages:column body after:why"', '"ms.messages:column chat_id, seq, sender_id, bot_id, cr_cb6d8c70"', '"ms.messages:column chat_id, se